    // Depth of the buffer (2-deep as requested)
    localparam DEPTH = 2;

    // Source domain state
    // Stores the valid/ready handshake state for the source domain
    typedef enum logic [1:0] {
        SRC_IDLE,
        SRC_WAIT_DST,
        SRC_FULL
    } src_state_t;

