    logic [WIDTH-1:0] src_data_reg;
    logic src_valid_reg;

    // Destination domain state
    // Stores the valid/ready handshake state for the destination domain
    typedef enum logic [1:0] {
        DST_IDLE,
        DST_WAIT_SRC,
        DST_FULL
